import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"中吕·朝天子山中杂书三首","description":"","frontmatter":{"title":"中吕·朝天子山中杂书三首","date":"2026-11-11T00:00:00.000Z","seq":3,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/中吕·朝天子山中杂书三首.md","filePath":"blogs/元曲·张可久/中吕·朝天子山中杂书三首.md"}'),o={name:"blogs/元曲·张可久/中吕·朝天子山中杂书三首.md"};function c(l,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="中吕·朝天子山中杂书三首" tabindex="-1">中吕·朝天子山中杂书三首 <a class="header-anchor" href="#中吕·朝天子山中杂书三首" aria-label="Permalink to &quot;中吕·朝天子山中杂书三首&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">罢手，去休，已落在渊明后。</p><p class="poem-stanza">百年心事付沙鸥，更谁是忘机友。</p><p class="poem-stanza">洞口渔舟，桥边村酒，这清闲何处有？树头，锦鸠，花外啼春昼。</p><p class="poem-stanza">夜长，未央，盼杀鸡三唱。</p><p class="poem-stanza">东华听漏满靴霜，却笑渊明强。</p><p class="poem-stanza">月朗禅床，风清鹤帐，梦不到名利场。</p><p class="poem-stanza">草堂，暗香，春已到梅梢上。</p><p class="poem-stanza">醉馀，草书，李愿盘谷序。</p><p class="poem-stanza">青山一片范宽图，怪我来何暮？鹤骨清癯，蜗壳蘧庐，得安闲心自足。</p><p class="poem-stanza">蹇驴，和酒壶，风雪梅花路。</p><p class="poem-stanza">野景亭瓜田邵平，草堂杜陵，五柳庄彭泽令。</p><p class="poem-stanza">牵牛篱落掩柴荆，犬吠林塘静。</p><p class="poem-stanza">树顶蟾明，水面风生，听渔歌三四声。</p><p class="poem-stanza">小亭，野景，动著我莼鲈兴。</p><p class="poem-stanza">酸斋席上听胡琴玉鞭，翠钿，记马上昭君面。</p><p class="poem-stanza">一梭银线解冰泉，碎拆骊珠串。</p><p class="poem-stanza">雁舞秋烟，莺啼春院，伤心塞草边。</p><p class="poem-stanza">醉仙，彩笺，写万里关山怨。</p><p class="poem-stanza">春思见他，问咱，怎忘了当初话？东风残梦小窗纱，月冷秋千架。</p><p class="poem-stanza">自把琵琶，灯前弹罢，春深不到家。</p><p class="poem-stanza">五花，骏马，何处垂杨下。</p><p class="poem-stanza">梅友元帅席上老夫，病余，尚草《长门赋》。</p><p class="poem-stanza">阿莲娇吻贯骊珠，试听《莺啼序》。</p><p class="poem-stanza">玉露冰壶，香风琼树，醉归来不用扶。</p><p class="poem-stanza">小奴，按舞，看了梅花去。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
